sksl:
uniform shader image;
uniform float2 size;
uniform float time;
layout(color) uniform half4 colorA;
layout(color) uniform half4 colorB;
uniform float mode;
uniform float angle;
uniform float2 center;
uniform float repeatCount;
uniform float mirror;
uniform float scroll;
uniform float keepTexture;
uniform float opacity;
float4 texT(float2 p) {
    return float4(image.eval(p));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
float luma(float3 c) {
    return dot(c, float3(0.2126, 0.7152, 0.0722));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = texT(coord);
    float3 s = unp(c);
    float2 d = coord / size - center;
    float t = dot(coord / size - float2(0.5), float2(cos(radians(angle)), sin(radians(angle)))) + 0.5;
    if (mode > 0.5 && mode < 1.5) t = length(d * float2(size.x / size.y, 1.0)) * 1.4142;
    else if (mode > 1.5) t = atan(d.y, d.x) / 6.2831853 + 0.5;
    t = fract(t * repeatCount + time * scroll);
    if (mirror > 0.5) t = 1.0 - abs(2.0 * t - 1.0);
    float3 fill = mix(float3(colorA.rgb), float3(colorB.rgb), t);
    float3 o = mix(fill, fill * luma(s) * 2.0, keepTexture);
    return fin(c, float4(saturate(o) * c.a, c.a), opacity);
}
